param(\n    [int]$IntervalMinutes = 30,\n    [int]$MaxPages = 100,\n    [int]$MaxItems = 100\n)\n\n$ErrorActionPreference = "Stop"\n$TaskName = "STECH Product Autofill"\n$RepoRoot = (Resolve-Path (Join-Path $PSScriptRoot "..\..")).Path\n$Runner = Join-Path $RepoRoot "deploy\windows\RUN_AUTOFILL_CYCLE.ps1"\n\nif ($IntervalMinutes -lt 5) { throw "IntervalMinutes must be at least 5." }\nif (-not (Test-Path $Runner)) { throw "Runner not found: $Runner" }\n\n$arguments = "-NoProfile -ExecutionPolicy Bypass -File `"$Runner`" -MaxPages $MaxPages -MaxItems $MaxItems"\n$action = New-ScheduledTaskAction -Execute "powershell.exe" -Argument $arguments -WorkingDirectory $RepoRoot\n\n$logonTrigger = New-ScheduledTaskTrigger -AtLogOn\n$repeatTrigger = New-ScheduledTaskTrigger -Once -At (Get-Date).AddMinutes(1) -RepetitionInterval (New-TimeSpan -Minutes $IntervalMinutes) -RepetitionDuration (New-TimeSpan -Days 3650)\n\n$settings = New-ScheduledTaskSettingsSet -StartWhenAvailable -MultipleInstances IgnoreNew -ExecutionTimeLimit (New-TimeSpan -Hours 2)\n$principal = New-ScheduledTaskPrincipal -UserId "$env:USERDOMAIN\$env:USERNAME" -LogonType Interactive -RunLevel Limited\n\nRegister-ScheduledTask -TaskName $TaskName -Action $action -Trigger @($logonTrigger, $repeatTrigger) -Settings $settings -Principal $principal -Description "Scans STECH Product Workspace, queues missing technical/image work and processes Product Work jobs." -Force | Out-Null\n\nStart-ScheduledTask -TaskName $TaskName\nWrite-Host "$TaskName installed and started."\nWrite-Host "Interval: every $IntervalMinutes minutes + at logon."\nWrite-Host "Log: $RepoRoot\logs\autofill-cycle.log"\n